window.ALFRED_WEEKS = [{"week":1,"topic":"Electricity Basics + Safety + Ohm/Watt","start":"2026-09-08","end":"2026-09-12","outcomes":["Explain voltage, current, resistance, power, ground/reference, polarity, open circuits, and short circuits.","Use SI prefixes and engineering notation correctly for common electronic values.","Apply Ohm's law and the Watt/power relationships to simple DC circuits.","Recognize basic electrical hazards and use safe low-voltage measurement habits.","Solve Ohm's law and power problems with units and SI prefixes.","Predict current, voltage drop, resistance, and power before measuring.","Explain why current limiting and correct meter connections matter.","Relate calculated voltage/current/power to what a DMM measures on a real circuit."]},{"week":2,"topic":"DC Networks + KVL/KCL + Voltage Dividers + DMM","start":"2026-09-14","end":"2026-09-19","outcomes":["Analyze series and parallel resistor networks.","Use Kirchhoff's Voltage Law and Kirchhoff's Current Law to reason about circuit behavior.","Design and analyze a voltage divider, including the effect of loading.","Predict node voltages, branch currents, equivalent resistance, and power.","Calculate equivalent resistance, node/branch values, divider outputs, and power.","Use KVL/KCL to check whether calculated results are internally consistent.","Use a DMM to verify a DC network and explain differences between predicted and measured values.","Troubleshoot opens, shorts, wrong resistor values, and wiring mistakes systematically."]},{"week":3,"topic":"DMM + Bench Supply + Oscilloscope","start":"2026-09-21","end":"2026-09-26","outcomes":["Select the correct DMM mode for voltage, resistance, continuity, current, and diode checks.","Explain correct meter placement and why current measurements are different from voltage measurements.","Set a bench supply voltage and current limit and distinguish constant-voltage from constant-current operation.","Explain oscilloscope volts/div, time/div, triggering, coupling, probe attenuation, and bandwidth at a basic working level.","Interpret instrument ranges/specifications and choose safe measurement setups.","Predict what the DMM/supply/scope should show before connecting it.","Use proper oscilloscope grounding and understand the hazard of earth-referenced probe grounds.","Measure a real low-voltage signal with a DMM, bench supply, and oscilloscope and interpret the result."]},{"week":4,"topic":"AC Waveforms + R/C/L Behavior","start":"2026-09-28","end":"2026-10-03","outcomes":["Describe sine waves and basic AC quantities: amplitude, peak, peak-to-peak, frequency, period, phase, and RMS.","Convert between frequency and period and interpret waveform measurements.","Explain how capacitors and inductors store energy and oppose changes in voltage or current.","Describe RC and RL transient behavior and the idea of a time constant.","Calculate frequency/period, RMS or peak relationships where assigned, and basic RC timing quantities.","Read waveform scales accurately and connect numerical results to scope displays.","Recognize basic low-pass and high-pass behavior.","Use an oscilloscope to connect waveform theory to measured circuit behavior."]},{"week":5,"topic":"Foundation Mastery Check","start":"2026-10-05","end":"2026-10-10","outcomes":["Integrate Weeks 1-4 without relying on isolated memorized facts.","Solve mixed DC/AC, Ohm/Watt, series/parallel, KVL/KCL, divider, waveform, and passive-component problems.","Choose the correct test instrument and measurement method for a stated problem.","Build, measure, and fault-isolate a simple circuit independently.","Document weak areas and repair them before calling the foundation complete."]},{"week":6,"topic":"Reactance + Impedance + Resonance + Filters + Transformers","start":"2026-10-12","end":"2026-10-17","outcomes":["Explain capacitive reactance, inductive reactance, impedance, and their dependence on frequency.","Recognize the relationship among resistance, reactance, impedance, voltage, current, and phase.","Explain resonance and the role of inductance and capacitance in tuned behavior.","Describe basic low-pass, high-pass, band-pass, and band-stop filter behavior.","Calculate basic XL, XC, impedance/ratio/resonance relationships at the assigned CETa depth.","Predict how changing frequency changes circuit behavior.","Explain transformer turns ratio, voltage/current relationships, isolation, and basic loading ideas.","Use calculations, simulation, or measurements to verify frequency-dependent circuit behavior."]},{"week":7,"topic":"Components + Magnetism + Motors/Generators + Relays","start":"2026-10-19","end":"2026-10-24","outcomes":["Identify common passive component families, ratings, tolerances, markings, and practical failure modes.","Explain basic magnetic-field, electromagnet, relay, motor, generator, and alternator concepts.","Distinguish relay coils/contacts and understand why inductive loads need suppression.","Explain the role of resistors, capacitors, inductors, transformers, switches, fuses, and relays in real circuits.","Interpret ratings, tolerance, coil/contact values, and basic electromechanical relationships.","Select parts from markings/datasheets and justify the choice.","Use datasheets/markings and measurements to verify a component or electromechanical device.","Recognize common component-level faults and the symptoms they create."]},{"week":8,"topic":"Semiconductors + Switching Devices","start":"2026-10-26","end":"2026-10-31","outcomes":["Explain PN junction behavior and the operation/use of rectifier diodes, LEDs, Zener diodes, and protection diodes.","Explain BJT switching at a practical level and distinguish NPN/PNP behavior.","Explain FET/MOSFET gate control, source/drain roles, logic-level switching, and common protection concerns.","Recognize SCR/TRIAC purpose and where controlled switching devices are used.","Reason about diode drops, current limiting, transistor/MOSFET switching conditions, and device ratings.","Recognize whether a semiconductor device is being used safely within its stated limits.","Select and wire a basic transistor/MOSFET switch with appropriate current limiting/flyback protection.","Troubleshoot common semiconductor-switching faults with a meter or scope."]},{"week":9,"topic":"Electronic Power Supplies","start":"2026-11-02","end":"2026-11-07","outcomes":["Describe the functional blocks of an electronic power supply: transformation/conversion, rectification, filtering, regulation, and protection.","Explain half-wave/full-wave/bridge rectification and the purpose of filter capacitors.","Distinguish basic linear regulation from switching regulation.","Explain ripple, load regulation, line regulation, efficiency, and current limiting at a practical level.","Calculate or estimate rectified/filter/regulator output and basic power/efficiency/ripple relationships at assigned depth.","Use measured rails to isolate which supply block is failing.","Recognize protection devices and likely failure points in a supply.","Measure input/output rails and use symptoms to isolate a power-supply fault."]},{"week":10,"topic":"Amplifiers + Op-Amps + Gain","start":"2026-11-09","end":"2026-11-14","outcomes":["Explain voltage gain, current gain, power gain, loading, input/output impedance, and feedback.","Use decibels at a basic technician level and relate dB changes to gain/loss.","Distinguish common amplifier classes and basic transistor/FET amplifier roles.","Explain ideal op-amp assumptions at an introductory level.","Calculate basic voltage/power gain and dB relationships.","Predict amplifier output limits and identify clipping/loading from numerical or waveform evidence.","Recognize inverting, non-inverting, buffer/comparator-style applications and the role of feedback.","Measure or simulate an amplifier and diagnose clipping, bias, loading, or gain problems."]},{"week":11,"topic":"Digital Logic + Number Systems","start":"2026-11-16","end":"2026-11-21","outcomes":["Convert among binary, decimal, and hexadecimal and use binary place value confidently.","Explain Boolean logic and the behavior/truth tables of NOT, AND, OR, NAND, NOR, XOR, and XNOR.","Distinguish combinational from sequential logic and recognize latches/flip-flops/counters at a basic level.","Explain logic-high/logic-low levels, noise margins, pull-ups/pull-downs, floating inputs, and open-drain/open-collector concepts.","Convert binary/decimal/hex, complete truth tables, and evaluate Boolean expressions.","Use logic-state reasoning to predict digital outputs.","Recognize memory, buses, ports, and basic digital-system blocks.","Verify digital behavior using truth tables, simulation, or measured logic signals."]},{"week":12,"topic":"Soldering + Git + Cumulative Repair","start":"2026-11-23","end":"2026-11-28","outcomes":["Explain ESD risk and use basic ESD-safe handling practices.","Prepare, solder, inspect, desolder, and rework basic through-hole/header connections safely.","Repair any previously identified weak concept before treating it as mastered."]},{"week":13,"topic":"Schematics + Troubleshooting","start":"2026-11-30","end":"2026-12-05","outcomes":["Read basic schematics, block diagrams, wiring diagrams, pinouts, connector tables, and signal-flow drawings.","Trace power and signals from source to destination and relate schematic symbols to physical hardware.","Use datasheets to find pin functions, ratings, timing, operating conditions, and reference circuits.","Apply a systematic troubleshooting loop: verify symptom, gather evidence, divide/isolate, form hypothesis, test, repair, verify.","Use diagram/signal-path information to choose measurement points and isolate a fault.","Interpret expected values from a schematic before probing.","Use signal tracing, substitution/known-good comparison, continuity, voltage, and waveform checks appropriately.","Distinguish root cause from symptom and document a defensible troubleshooting conclusion."]},{"week":14,"topic":"C Programming I + Computer Architecture","start":"2026-12-07","end":"2026-12-12","outcomes":["Explain the build path from C source through compiler/linker to an executable/firmware image.","Use integer types, fixed-width types, variables, operators, conditionals, loops, functions, arrays, strings, structs, and enums.","Explain scope, lifetime, and basic memory organization.","Describe CPU, RAM, flash, buses, peripherals, registers, inputs, and outputs in a microcontroller/computer system.","Write and explain a small C program from scratch rather than copying a tutorial.","Connect software operations conceptually to hardware resources."]},{"week":15,"topic":"C Programming II + Embedded C + State Machines","start":"2026-12-14","end":"2026-12-19","outcomes":["Use pointers, addresses, dereferencing, arrays/pointers, structs, and function interfaces safely at a practical level.","Use bitwise AND/OR/XOR, shifts, masks, and set/clear/test operations for hardware-oriented code.","Explain const, volatile, macros, headers/modules, and compiler warnings in embedded C.","Distinguish blocking from nonblocking behavior.","Work bit-mask/shift examples and pointer/address reasoning without guessing.","Trace state-machine transitions and timing/interrupt-related behavior.","Design and implement a finite-state machine for simple embedded behavior.","Explain the role of interrupts/timers conceptually and write modular code that is easier to test/debug."]},{"week":16,"topic":"STM32 Setup + GPIO + SWD Debug","start":"2026-12-21","end":"2026-12-26","outcomes":["Explain what an MCU and ARM Cortex-M core are and identify flash, RAM, GPIO, clocks, and peripherals in an STM32 system.","Create/configure a basic STM32 project in STM32CubeIDE/CubeMX.","Configure GPIO input/output and understand pin multiplexing at a working level.","Build, flash, run, and reset firmware on a real board.","Use SWD debugging: breakpoints, single-step, watch variables, and basic register inspection.","Separate a firmware problem from a board/power/configuration problem during bring-up."]},{"week":17,"topic":"UART + Python Serial","start":"2026-12-28","end":"2027-01-02","outcomes":["Explain UART TX, RX, ground/reference, baud rate, frame format, and asynchronous serial communication.","Send and receive UART data between an STM32 and a host computer.","Use a terminal/serial monitor to inspect traffic and diagnose basic framing/configuration problems.","Use Python/pySerial to open a port, configure timeout/baud, send commands, read responses, and close cleanly.","Parse and log basic device responses from Python.","Explain how a host-side application can test or control an embedded device."]},{"week":18,"topic":"I2C/SPI + Logic Analyzer + Sensors/Actuators","start":"2027-01-04","end":"2027-01-09","outcomes":["Explain I2C controller/target roles, SDA/SCL, addressing, pull-ups, start/stop, read/write, ACK/NACK, and basic transactions.","Explain SPI controller/peripheral roles, SCLK, MOSI, MISO, chip select, transaction framing, and the idea of clock mode.","Choose I2C or SPI appropriately for a simple peripheral and wire it correctly.","Use a logic analyzer to capture and decode UART and the chosen I2C/SPI bus.","Integrate a real sensor/peripheral and convert raw data into meaningful units.","Interface a digital input/output or actuator safely and verify the end-to-end signal path."]},{"week":19,"topic":"Cabling + Audio/Video + Optical","start":"2027-01-12","end":"2027-01-16","outcomes":["Recognize common cable, connector, transmission-media, audio/video, and optical/fiber concepts in the CETa scope.","Explain basic impedance, shielding, grounding, connector integrity, continuity, and signal-loss concerns for cabling.","Describe basic audio/video signal paths and common failure points at a technician level.","Explain basic optical/fiber concepts, source/path/receiver thinking, attenuation, and handling cautions.","Select appropriate basic test/troubleshooting methods for cables and media.","Distinguish this CETa breadth knowledge from the deeper embedded/hardware core."]},{"week":20,"topic":"RF + Telecom + Technician Procedures","start":"2027-01-19","end":"2027-01-23","outcomes":["Explain introductory RF concepts: frequency bands, propagation, modulation, transmission lines, antennas, and standing-wave/impedance ideas at CETa level.","Recognize basic transmitter/receiver and telecom/telephone signal-path concepts.","Understand technician procedures involving documentation, records, professionalism, and technical communication.","Relate RF/telecom symptoms to likely path, connector, configuration, or signal problems.","Use the CETa references to recognize terminology without over-studying material that is not central to the bridge-job path.","Integrate broad CETa knowledge with the electronics/test foundation already built."]},{"week":21,"topic":"CETa Final Review I","start":"2027-01-26","end":"2027-01-30","outcomes":["Recall and apply the core formula families required by the current CETa scope.","Identify common components, symbols, diagrams, instruments, and safety practices quickly and accurately.","Choose the correct measurement/test method from a scenario.","Navigate mixed electronics questions without relying on one-topic-at-a-time cues.","Identify weak competency numbers and repair specific gaps instead of rereading everything.","Demonstrate readiness for full-length CETa practice work."]},{"week":22,"topic":"CETa Final Review II + Project 1 Design","start":"2027-02-02","end":"2027-02-06","outcomes":["Repair remaining CETa weak areas using exact competency evidence.","Translate a real embedded project idea into clear requirements and acceptance criteria.","Repair any previously identified weak concept before treating it as mastered.","Create a block diagram, interface list, pin map, BOM, and initial test plan.","Control Project 1 scope so it proves bridge-job skills without feature creep.","Explain how each Project 1 feature maps to a readiness-checklist skill.","Use current CETa practice performance to decide whether exam readiness is green, yellow, or red."]},{"week":23,"topic":"CETa Readiness Gate + Project Setup","start":"2027-02-09","end":"2027-02-13","outcomes":["Complete the CETa readiness gate using current practice performance and targeted repairs.","Organize the Project 1 repository, folders, README skeleton, issue list, and evidence locations.","Prepare the bench, board, cables, instruments, firmware toolchain, and parts for controlled bring-up.","Confirm Project 1 requirements, interfaces, test cases, and safety limits before powering hardware.","Distinguish 'ready to build' from 'still collecting resources.'","Begin Project 1 with a reproducible, documented setup."]},{"week":24,"topic":"Project 1 Hardware Bring-Up","start":"2027-02-16","end":"2027-02-20","outcomes":["Perform safe first power-up using visual inspection, continuity checks, a current-limited supply, and measured power rails.","Verify board power, ground, reset/boot conditions, GPIO, and UART before adding complexity.","Measure voltage/current and record baseline current draw.","Use SWD/UART diagnostics to separate hardware, firmware, and configuration faults.","Apply staged bring-up rather than powering everything at once.","Document bring-up evidence and any fault/recovery story."]},{"week":25,"topic":"Project 1 Sensor / Interface Integration","start":"2027-02-23","end":"2027-02-27","outcomes":["Integrate the chosen I2C/SPI sensor or peripheral into Project 1.","Read raw registers/data and convert values into meaningful engineering units.","Verify bus activity with a logic analyzer and correlate decoded traffic with firmware behavior.","Handle missing device, wrong address/configuration, timeout, or invalid-data conditions.","Confirm electrical interface requirements from the datasheet.","Document a working end-to-end peripheral path from hardware through firmware to observed output."]},{"week":26,"topic":"Project 1 Firmware Architecture","start":"2027-03-02","end":"2027-03-06","outcomes":["Organize Project 1 firmware into understandable modules with clear responsibilities.","Use a nonblocking finite-state machine for system behavior.","Use timers/interrupts where appropriate without creating timing-dependent chaos.","Implement timeouts, error states, diagnostic messages, and recoverable fault handling.","Use const/volatile/bit operations appropriately in hardware-facing code.","Debug firmware systematically and explain the architecture without relying on generated code alone."]},{"week":27,"topic":"Python Hardware Test + Automated Logger","start":"2027-03-09","end":"2027-03-13","outcomes":["Build a Python host/test tool that communicates with the DUT over serial.","Define commands/responses and parse them robustly.","Log timestamped results to CSV/JSON or another structured format.","Turn requirements into repeatable PASS/FAIL checks using assertions/pytest-style logic.","Handle timeouts, malformed responses, and device faults without silently passing.","Plot or summarize test data so trends/failures are visible and preserve evidence for the portfolio."]},{"week":28,"topic":"Fault Injection + Troubleshooting + Test Report","start":"2027-03-16","end":"2027-03-20","outcomes":["Design and execute deliberate fault-injection tests.","Use the troubleshooting sequence: reproduce, measure, isolate, hypothesize, test, fix, and verify.","Distinguish hardware, firmware, interface, test-fixture, power, and host-script faults.","Collect DMM/scope/logic-analyzer/log evidence that supports root cause."]},{"week":29,"topic":"Instrumentation + Solder/Rework/Harness Role Proof","start":"2027-03-23","end":"2027-03-27","outcomes":["Use DMM, oscilloscope, logic analyzer, bench supply, and debugger evidence confidently in one coherent hardware story.","Demonstrate clean soldering/rework, wire termination, continuity verification, and simple harness/prototype workmanship.","Perform a controlled prototype repair or rework and verify the result.","Create an R&D/engineering-lab role-proof dossier: prototype, bring-up, problem, measurements, repair, retest.","Explain workmanship/ESD/safety decisions professionally.","Show that the physical build is understandable and serviceable by another technical person."]},{"week":30,"topic":"Portfolio + Resume + Interview Green-Light","start":"2027-03-30","end":"2027-04-03","outcomes":["Present Project 1 as an employer-facing engineering artifact rather than a hobby build.","Write truthful, role-specific resume bullets for R&D electronics, hardware test/validation, and integration roles.","Organize GitHub/portfolio evidence so a reviewer can understand the problem, design, measurements, failures, and results quickly.","Deliver a clear 90-second career-transition story and a 2-minute/5-minute Project 1 explanation.","Defend your own C, Python, electronics, instruments, protocols, and troubleshooting decisions in interview questions.","Apply the bridge-job green-light criteria: permanent/full-time, acceptable compensation/benefits, school-compatible, and genuinely hardware/electronics relevant."]},{"week":31,"topic":"Application Sprint + Interview Feedback Loop","start":"2027-04-06","end":"2027-04-10","outcomes":["Practice technical and behavioral interviews using real project/troubleshooting stories.","Track interview misses and convert them into dated learning repairs.","Maintain the portfolio while applying without restarting the entire curriculum.","Use market feedback to refine role targeting while preserving the embedded-systems trajectory."]}];
